arguments.command:
git checkout origin/main -- src/push.ts && python3 - <<'EOF'
p='src/push.ts'
s=open(p).read()
R=[('''// The action's `if: always()` step: push the thread ref if the main step left commits unpushed (cancelled,
// timed out, or crashed).''','''// The action's `if: always()` step: push the thread ref (with its working-tree snapshots) if the main step left
// commits unpushed (cancelled, timed out, or crashed).'''),
('import { GitSync } from "./storage/sync.ts";\n','import { GitSync } from "./storage/sync.ts";\nimport { worktreeRef } from "./storage/worktree.ts";\n'),
('''	try {
		const sync = new GitSync({ repo: cwd, ref, log: log.info });
		if ((await sync.remoteHead()) === tip) {
			log.info(`${ref} is already saved at ${tip.slice(0, 7)}`);
			return "up-to-date";
		}
		await sync.flush(tip);''','''	// The working-tree snapshots, when the main step saved any.
	const companionRef = worktreeRef(number);
	const companion = (
		await git(cwd, ["rev-parse", "--verify", "-q", companionRef]).catch(
			() => "",
		)
	).trim();
	try {
		const sync = new GitSync({ repo: cwd, ref, companionRef, log: log.info });
		const remote = await sync.remoteHeads();
		if (
			remote.tip === tip &&
			(companion === "" || remote.companion === companion)
		) {
			log.info(`${ref} is already saved at ${tip.slice(0, 7)}`);
			return "up-to-date";
		}
		await sync.flush(tip, companion || undefined);'''),
]
for a,b in R:
    assert a in s,a
    s=s.replace(a,b)
open(p,'w').write(s)

p='action.yml'
s=open(p).read()
a='''        INPUT_PR_NUMBER: ${{ inputs.pr_number }}
        INPUT_WORKTREE_SNAPSHOTS: ${{ inputs.worktree_snapshots }}
        INPUT_WORKTREE_SNAPSHOT_MAX_FILE_MB: ${{ inputs.worktree_snapshot_max_file_mb }}
        INPUT_WORKTREE_SNAPSHOT_MAX_TOTAL_MB: ${{ inputs.worktree_snapshot_max_total_mb }}
        INPUT_WORKTREE_SNAPSHOT_EXCLUDE: ${{ inputs.worktree_snapshot_exclude }}
'''
assert a in s
s=s.replace(a,'        INPUT_PR_NUMBER: ${{ inputs.pr_number }}\n')
s=s.replace('''    # Pushes the thread's refs/pi/threads/<number> (and refs/pi/worktrees/<number>, after saving the working tree
    # once more) if the step above''','''    # Pushes the thread's refs/pi/threads/<number> (and refs/pi/worktrees/<number>) if the step above''')
open(p,'w').write(s)
EOF
sed -n '/# Pushes the thread/,+3p' action.yml; git diff origin/main -- src/inputs.ts | grep "^[-+]export"
